 const patina=new Uint8Array(64*64*4);for(let i=0;i<4096;i++){const n=(Math.sin(i*12.9898)*43758.5453)%1,v=Math.abs(n),rust=v>.86;patina.set(rust?[105+v*30,72,43,255]:[155+v*35,165+v*35,157+v*35,255],i*4);}const texture=new THREE.DataTexture(patina,64,64,THREE.RGBAFormat);texture.colorSpace=THREE.SRGBColorSpace;texture.needsUpdate=true;metal.map=texture;metal.bumpMap=texture;metal.bumpScale=.012;for(const side of [-1,1])sphere(.16,metal,side*.38,1.66,0,robot,1,.8,1);sphere(.23,metal,0,2.02,-.035,robot,1.12,.85,.8);for(let i=0;i<3;i++){const neck=new THREE.Mesh(new THREE.TorusGeometry(.085,.018,7,16),copper);neck.rotation.x=Math.PI/2;neck.position.y=1.72+i*.04;robot.add(neck);}box(.62,.64,.34,metal,0,1.42,0,robot);box(.48,.3,.37,dark,0,1.03,0,robot);box(.42,.35,.37,metal,0,1.96,0,robot);box(.34,.16,.025,dark,0,2.01,.2,robot);const eye=new THREE.MeshStandardMaterial({color:0x34534c,emissive:0x76d3bf,emissiveIntensity:0});for(const x of [-.09,.09])sphere(.046,eye,x,2.02,.23,robot,1,1,.6);
 for(let i=0;i<5;i++)box(.22,.018,.025,dark,0,1.86+i*.025,.2,robot);for(const x of [-.24,.24])for(const y of [1.2,1.65])sphere(.024,copper,x,y,.18,robot);
 for(const x of [-.105,.105]){const ring=new THREE.Mesh(new THREE.TorusGeometry(.081,.018,8,20),copper);ring.position.set(x,2.02,.235);robot.add(ring);sphere(.063,dark,x,2.02,.232,robot,1,1,.6);sphere(.037,eye,x,2.02,.27,robot,1,1,.5);}for(let i=0;i<7;i++)box(.25,.018,.03,dark,0,1.3+i*.045,.19,robot);for(const side of [-1,1]){box(.07,.42,.05,copper,side*.265,1.43,.21,robot);for(let i=0;i<4;i++)sphere(.018,dark,side*.265,1.25+i*.12,.245,robot);}const legs=[],arms=[];for(const side of [-1,1]){const leg=new THREE.Group();leg.position.set(side*.2,.96,0);robot.add(leg);sphere(.105,dark,0,0,0,leg);box(.16,.38,.19,metal,0,-.25,0,leg);const knee=new THREE.Group();knee.position.y=-.48;leg.add(knee);sphere(.09,copper,0,0,0,knee);box(.13,.34,.17,metal,0,-.20,0,knee);box(.21,.10,.34,dark,0,-.41,.08,knee);box(.035,.29,.04,copper,.1,-.24,.11,leg);box(.04,.24,.04,copper,-.09,-.18,.1,knee);legs.push({leg,knee});const arm=new THREE.Group();arm.position.set(side*.4,1.65,0);robot.add(arm);sphere(.11,dark,0,0,0,arm);box(.14,.35,.15,metal,0,-.22,0,arm);sphere(.08,copper,0,-.44,0,arm);box(.12,.3,.14,metal,0,-.62,.02,arm);box(.16,.13,.08,dark,0,-.83,.04,arm);for(let i=0;i<3;i++)box(.028,.12,.035,metal,(i-1)*.045,-.94,.04,arm);arms.push(arm);}
 for(const side of [-1,1]){const curve=new THREE.CatmullRomCurve3([new THREE.Vector3(side*.24,1.65,-.18),new THREE.Vector3(side*.35,1.2,-.25),new THREE.Vector3(side*.2,.95,-.2)]);robot.add(new THREE.Mesh(new THREE.TubeGeometry(curve,12,.018,5,false),copper));}
 const scars=[];for(let i=0;i<160;i++){const x=Math.sin(i*73)*.29,y=1.12+(i%17)*.033;scars.push(x,y,.177,x+.015+(i%3)*.01,y+.01,.178);}const sg=new THREE.BufferGeometry();sg.setAttribute('position',new THREE.Float32BufferAttribute(scars,3));robot.add(new THREE.LineSegments(sg,new THREE.LineBasicMaterial({color:0x453e31,transparent:true,opacity:.65})));const silk=[];for(let i=0;i<18;i++){silk.push(-.6,2.3-i*.085,.25,.55,.6+i*.065,.26);}const wg=new THREE.BufferGeometry();wg.setAttribute('position',new THREE.Float32BufferAttribute(silk,3));robot.add(new THREE.LineSegments(wg,new THREE.LineBasicMaterial({color:0xb2bfb4,transparent:true,opacity:.5})));
 box(.8,.12,.7,0x3f4847,11.6,H+.52,-43.5);glow(0x84b3a6,2,8,10.7,H+2.9,-41);
 const battery=new THREE.Group();battery.name='Robot power cell';box(.28,.16,.4,0x31535b,0,0,0,battery);box(.17,.02,.28,0x9bc7b3,0,.09,0,battery);for(const x of [-.07,.07])box(.04,.03,.05,copper,x,.11,-.12,battery);battery.position.set(7.2*W,.1,10.5);scene.add(battery);
 let retreat=-1;return{door,barrier,robot,battery,slab:{x:10.75,z:-41.5,w:3.5,d:6.5,bottom:H-.22,top:H},reset(){retreat=-1;door.visible=true;barrier.top=H+3.4;battery.visible=true;robot.position.set(10.7,H,-42);robot.rotation.y=0;eye.emissiveIntensity=0;for(const {leg,knee}of legs){leg.rotation.x=0;knee.rotation.x=0;}},wake(){eye.emissiveIntensity=.8;},rest(){retreat=0;},update(dt,time){if(retreat<0)return;retreat+=dt;const u=Math.min(1,retreat/4);robot.position.x=10.7+u*.9;robot.position.z=-42-u*1.5;for(let i=0;i<legs.length;i++){legs[i].leg.rotation.x=u<1?Math.sin(time*5+i*Math.PI)*.3:-1.3;legs[i].knee.rotation.x=u<1?.15:1.4;arms[i].rotation.x=u<1?-Math.sin(time*5+i*Math.PI)*.15:-.3;}if(u===1)robot.position.y=H-.4;}};
